        :root { --ocean: #0f766e; --green: #16a34a; --ink: #102a43; --muted: #627d98; } * { box-sizing: border-box; } body { margin: 0; min-height: 100vh; font-family: 'DM Sans', sans-serif; color: var(--ink); background: #effcf7; } .auth-shell { min-height: 100vh; display: grid; grid-template-columns: minmax(280px, .9fr) minmax(360px, 1.1fr); overflow: hidden; } .auth-brand { position: relative; display: flex; flex-direction: column; justify-content: space-between; padding: clamp(28px, 6vw, 76px); color: white; background: linear-gradient(145deg, #123b53 0%, #0f766e 52%, #16a34a 100%); } .auth-brand::after { content: ''; position: absolute; inset: auto -15% -18% auto; width: 390px; height: 390px; border: 1px solid rgba(255,255,255,.22); border-radius: 50%; box-shadow: 0 0 0 34px rgba(255,255,255,.06), 0 0 0 70px rgba(255,255,255,.04); } .brand-link { position: relative; z-index: 1; color: white; text-decoration: none; font: 800 28px Manrope, sans-serif; letter-spacing: -.04em; } .brand-link span { color: #a7f3d0; } .brand-copy { position: relative; z-index: 1; max-width: 490px; } .brand-copy h1 { margin: 0; font: 800 clamp(34px, 4vw, 58px)/1.05 Manrope, sans-serif; letter-spacing: -.05em; } .brand-copy p { max-width: 420px; margin: 22px 0 0; color: #d1fae5; font-size: 17px; line-height: 1.7; } .auth-panel { display: grid; place-items: center; padding: 32px 20px; background: rgba(255,255,255,.78); } .auth-card { width: min(100%, 450px); padding: clamp(24px, 5vw, 48px); border: 1px solid #d7f3e7; border-radius: 28px; background: rgba(255,255,255,.94); box-shadow: 0 24px 70px rgba(15, 118, 110, .13); } .auth-card h2 { margin: 0; font: 800 32px Manrope, sans-serif; letter-spacing: -.04em; } .auth-card .intro { margin: 10px 0 28px; color: var(--muted); line-height: 1.6; } .field { display: grid; gap: 8px; margin-top: 17px; } label { font-size: 14px; font-weight: 700; } input { width: 100%; border: 1px solid #cbded7; border-radius: 13px; padding: 13px 14px; color: var(--